import{_ as t,o as i,c as a,a3 as o}from"./chunks/framework.BlfGB29P.js";const h=JSON.parse('{"title":"","description":"","frontmatter":{"layout":"home","hero":{"name":"Heizöl to MQTT","text":"Heating-oil prices for Home Assistant","tagline":"Query public Esyoil and Heizöl24 price calculators and publish best prices plus provider offers through MQTT Discovery.","actions":[{"theme":"brand","text":"Installation","link":"/en/projects/heizoel-to-mqtt/installation"},{"theme":"alt","text":"GitHub","link":"https://github.com/rockbaer2007/heizoel-to-mqtt"}]},"features":[{"icon":"🛢️","title":"Heating-oil prices","details":"Fetch best prices for configured postal code, amount and delivery options."},{"icon":"📍","title":"Germany and Austria","details":"Price lookups for German and Austrian postal codes."},{"icon":"🧾","title":"Provider offers","details":"Up to six provider offers per source and amount with price per liter, price per 100 liters and total price."},{"icon":"🔎","title":"Esyoil and Heizöl24","details":"Public price calculator endpoints are queried and normalized."},{"icon":"🏠","title":"MQTT Discovery","details":"Home Assistant creates price, provider and status entities automatically."},{"icon":"🧰","title":"Diagnostics","details":"Optional masked provider logging for testing and troubleshooting."}]},"headers":[],"relativePath":"en/projects/heizoel-to-mqtt/index.md","filePath":"en/projects/heizoel-to-mqtt/index.md","lastUpdated":1793128957000}'),r={name:"en/projects/heizoel-to-mqtt/index.md"};function s(n,e,l,p,c,d){return i(),a("div",null,[...e[0]||(e[0]=[o('<h2 id="overview" tabindex="-1">Overview <a class="header-anchor" href="#overview" aria-label="Permalink to &quot;Overview&quot;">​</a></h2><p>Heizöl to MQTT is a Home Assistant app that publishes heating-oil prices through MQTT Discovery.</p><p>The app queries public price calculator endpoints and normalizes the best offer per source and amount. It is intended for Germany and Austria only.</p><div class="info custom-block"><p class="custom-block-title">Origin</p><p>This implementation is adapted from and inspired by the ioBroker adapter <a href="https://github.com/TA2k/ioBroker.heizoel" target="_blank" rel="noreferrer">TA2k/ioBroker.heizoel</a>.</p></div><h2 id="status" tabindex="-1">Status <a class="header-anchor" href="#status" aria-label="Permalink to &quot;Status&quot;">​</a></h2><p>The app is testable in Home Assistant and publishes values through MQTT Discovery. It supports best-price entities and up to six provider offers per source and amount.</p><p>The used price endpoints are public website endpoints and not officially documented stable APIs.</p><h2 id="pages" tabindex="-1">Pages <a class="header-anchor" href="#pages" aria-label="Permalink to &quot;Pages&quot;">​</a></h2><ul><li><a href="./installation">Installation</a></li><li><a href="./configuration">Configuration</a></li><li><a href="./entities">Entities</a></li><li><a href="./examples">Examples</a></li></ul>',9)])])}const m=t(r,[["render",s]]);export{h as __pageData,m as default};
